/** The certificate of insurance the vendor packet carries as its annex. */
export const vendorPacketAnnexBytes: Uint8Array = decode(ENCODED);

/** base64 to bytes, without assuming Node's Buffer or a bundler's polyfill. */
function decode(encoded: string): Uint8Array {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let at = 0; at < binary.length; at += 1) bytes[at] = binary.charCodeAt(at);
  return bytes;
}
